-- Which Claritia migrations from 090 on are in this database. 091, 093, 114 and 121 have nothing to look for: they're
-- safe to run again (122 replaces 121), and 135 removed what 102 added. Run each one marked false, in order.
select migration, applied from (values
  ('090', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'form_submit_all')),
  ('092', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'form_booking_shown_rep')),
  ('094', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'router_action_count')),
  ('095', to_regclass('public.routing_policies') is not null),
  ('096', to_regclass('public.routing_test_evidence') is not null),
  ('097', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'router_runs' and column_name = 'booking_active_at')),
  ('098', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'routing_reviews_spam')),
  ('099', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'meeting_invite_info')),
  ('100', to_regclass('public.workflow_folders') is not null),
  ('101', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'workflow_meetings')),
  ('103', to_regclass('public.submission_results') is not null),
  ('104', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'submission_result_get')),
  ('105', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'form_daily' and column_name = 'results')),
  ('106', to_regclass('public.form_uploads') is not null),
  ('107', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'workspaces' and column_name = 'brand_kit_id')),
  ('108', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'brand_kits' and column_name = 'book')),
  ('109', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'forms' and column_name = 'live_kit_id')),
  ('110', to_regclass('public.form_drafts') is not null),
  ('111', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'brand_kits' and column_name = 'skin')),
  ('112', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'brand_kits' and column_name = 'studio_css')),
  ('113', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'brand_kits' and column_name = 'studio_profile')),
  ('115', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'routing_past')),
  ('116', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'job_kind_removed')),
  ('117', to_regclass('public.form_slug_moves') is not null),
  ('118', to_regclass('public.link_domains') is not null),
  ('119', exists(select 1 from information_schema.columns where table_schema = 'public' and table_name = 'workspaces' and column_name = 'workflow_defaults_at')),
  ('120', to_regclass('public.plan_usage') is not null),
  ('122', exists(select 1 from pg_proc where proname = 'plan_caps' and prosrc like '%''starter'' then 6 when ''pro'' then 6%')),
  ('123', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'form_to_studio')),
  ('124', exists(select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'form_fill_channels')),
  ('135', to_regclass('public.team_domains') is not null),
  ('136', to_regclass('public.identity_settings') is null),
  ('137', exists(select 1 from pg_constraint where conname = 'saved_views_screen_check' and pg_get_constraintdef(oid) not like '%accounts%'))
) as v(migration, applied) order by migration;
